session_start();require __DIR__.'/../config/database.php';require __DIR__.'/../includes/helpers.php';require_login();
$error='';$destinations=$pdo->query('SELECT id,name FROM destinations WHERE is_active=1 ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$destinationId=(int)($_POST['destination_id']??0);$start=$_POST['start_date']??'';$end=$_POST['end_date']??'';$budget=(float)($_POST['budget']??0);$desc=trim($_POST['description']??'');$st=$pdo->prepare('SELECT id,name FROM destinations WHERE id=? AND is_active=1');$st->execute([$destinationId]);$dest=$st->fetch();if(!$name||!$destinationId||!$start||!$end||$budget<0)$error='Vui lòng nhập đầy đủ thông tin.';elseif(!$dest)$error='Điểm đến không hợp lệ. Hãy chọn từ danh sách.';elseif($end<$start)$error='Ngày kết thúc phải sau ngày bắt đầu.';if(!$error){$pdo->prepare('INSERT INTO trips(owner_id,name,destination_id,destination,start_date,end_date,budget,description,status) VALUES(?,?,?,?,?,?,?, ?,\'draft\')')->execute([$_SESSION['user']['id'],$name,$dest['id'],$dest['name'],$start,$end,$budget,$desc]);$id=$pdo->lastInsertId();$pdo->prepare('INSERT INTO trip_members(trip_id,user_id,member_role) VALUES(?,?,\'owner\')')->execute([$id,$_SESSION['user']['id']]);flash('success','Tạo chuyến đi thành công.');redirect('user/trip-detail.php?id='.$id);}}
$pageTitle='Tạo chuyến đi';include __DIR__.'/../includes/header.php';show_flash();
